+		if vagas > sala.Capacidade {
+			responderErro(w, http.StatusUnprocessableEntity, "VAGAS_ACIMA_DA_CAPACIDADE")
+			return
+		}
+		if vagas < ocupadas {
+			responderErro(w, http.StatusConflict, "VAGAS_ABAIXO_DOS_INSCRITOS")
+			return
+		}
